package br.com.mecaniQA.api.Repository;
import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Mappers.VeiculoResultSetMapper; import br.com.mecaniQA.api.Enums.*; import java.sql.*; import java.util.*; import java.time.*;
public class VeiculoRepository extends JdbcSupport implements Repository<Veiculo,Long>{ private static final VeiculoRepository INSTANCE=new VeiculoRepository();public static VeiculoRepository getInstance(){return INSTANCE;}
 public Veiculo cadastrar(Veiculo x){return save(x);}public List<Veiculo>listarTodos(){return findAll();}public Veiculo buscarPorId(Long id){return findById(id).orElse(null);}public Veiculo buscarPorPlaca(String p){return query("SELECT * FROM veiculos WHERE placa=?",new VeiculoResultSetMapper()::map,p).stream().findFirst().orElse(null);}public List<Veiculo>buscarPorClienteId(Long id){return query("SELECT * FROM veiculos WHERE id_cliente=?",new VeiculoResultSetMapper()::map,id);}public Veiculo atualizar(Long id,Veiculo x){x.setIdVeiculo(id);return update(x);}public Veiculo deletar(Long id){Veiculo x=buscarPorId(id);if(x!=null)deleteById(id);return x;}public int getTotalVeiculos(){return findAll().size();}public void limpar(){execute("DELETE FROM veiculos");}
 public Veiculo save(Veiculo x){long id=insert("INSERT INTO veiculos(id_cliente,placa,marca_modelo,ano,cor,numero_motor,numero_chassi,quilometragem,observacoes) VALUES(?,?,?,?,?,?,?,?,?)",x.getCliente().getIdCliente(),x.getPlaca(),x.getMarcaModelo(),x.getAno(),x.getCor(),x.getNumeroMotor(),x.getNumeroChassi(),x.getQuilometragem(),x.getObservacoes());x.setIdVeiculo(id);return x;}public Optional<Veiculo>findById(Long id){return query("SELECT * FROM veiculos WHERE id_veiculo=?",new VeiculoResultSetMapper()::map,id).stream().findFirst();}public List<Veiculo>findAll(){return query("SELECT * FROM veiculos ORDER BY id_veiculo",new VeiculoResultSetMapper()::map);}public Veiculo update(Veiculo x){int n=execute("UPDATE veiculos SET id_cliente=?,placa=?,marca_modelo=?,ano=?,cor=?,numero_motor=?,numero_chassi=?,quilometragem=?,observacoes=?,data_atualizacao=CURRENT_TIMESTAMP WHERE id_veiculo=?",x.getCliente().getIdCliente(),x.getPlaca(),x.getMarcaModelo(),x.getAno(),x.getCor(),x.getNumeroMotor(),x.getNumeroChassi(),x.getQuilometragem(),x.getObservacoes(),x.getIdVeiculo());return n==0?null:x;}public void deleteById(Long id){execute("DELETE FROM veiculos WHERE id_veiculo=?",id);}public boolean existsById(Long id){return !query("SELECT id_veiculo FROM veiculos WHERE id_veiculo=?",r->r.getLong(1),id).isEmpty();}
 private Veiculo map(ResultSet r)throws SQLException{Cliente c=new Cliente();setId(c,"idCliente",r.getLong("id_cliente"));Veiculo x=new Veiculo();setId(x,"idVeiculo",r.getLong("id_veiculo"));x.setCliente(c);x.setPlaca(r.getString("placa"));x.setMarcaModelo(r.getString("marca_modelo"));x.setAno(r.getInt("ano"));x.setCor(r.getString("cor"));x.setNumeroMotor(r.getString("numero_motor"));x.setNumeroChassi(r.getString("numero_chassi"));x.setQuilometragem(r.getDouble("quilometragem"));x.setObservacoes(r.getString("observacoes"));x.setDataAtualizacao(time(r,"data_atualizacao"));return x;}}
